input.command:
cat > /repo/intent.json <<'JSON_EOF'
{
  "meta": {
    "generatedFor": "wejscie dla generatora danych testowych (SBST / property-based / table-driven)",
    "specSource": "docs/SPEC.md",
    "specVersion": "1.4",
    "codeSource": "src/",
    "normativeSource": "docs/SPEC.md - w razie rozbieznosci obowiazuje SPEC, nie kod. Rozbieznosci wypisane w polu `specVsCode` kazdego targetu.",
    "conventions": {
      "specialValueEncoding": "Wartosci, ktorych JSON nie potrafi zapisac, podane sa jako string w polu `expr` albo jako element listy oznaczony sufiksem `@expr`. Generator musi je zmapowac: \"NaN\" -> Number.NaN, \"Infinity\" -> Number.POSITIVE_INFINITY, \"-Infinity\" -> Number.NEGATIVE_INFINITY, \"-0\" -> -0, \"undefined\" -> undefined, \"null\" -> null, \"Number.MAX_SAFE_INTEGER\" -> 9007199254740991, \"Number.MIN_VALUE\" -> 5e-324.",
      "expected": "`expectedPerSpec` to wartosc wymagana przez docs/SPEC.md. `currentCodeBehavior` (gdy obecne) to wartosc, ktora zwraca aktualny kod w src/ - jesli oba pola sa obecne i rozne, przypadek jest testem wykrywajacym blad implementacji.",
      "money": "calculateShipping operuje na PLN (float, 2 miejsca po przecinku). Cart operuje na groszach (integer)."
    }
  },

  "targets": [
    {
      "module": "src/pricing.ts",
      "function": "calculateShipping",
      "kind": "pure-function",
      "signature": "calculateShipping(weightKg: number, zone: string, isPremium: boolean): number",
      "returns": {
        "type": "number",
        "unit": "PLN",
        "constraint": "kwota nieujemna, zaokraglona do 2 miejsc po przecinku (Math.round(x*100)/100)",
        "minObservable": 9.6,
        "maxObservable": 119
      },

      "rules": [
        {
          "id": "SHIP-R1",
          "rule": "Stawka bazowa zalezy od strefy: \"PL\" = 12.00 PLN, \"EU\" = 29.00 PLN, dowolna inna wartosc = 79.00 PLN.",
          "specSection": "Sekcja 1: Koszt dostawy / Stawka bazowa wedlug strefy",
          "boundaries": [
            { "input": { "weightKg": 1, "zone": "PL", "isPremium": false }, "expectedPerSpec": 12, "note": "dokladne dopasowanie \"PL\"" },
            { "input": { "weightKg": 1, "zone": "EU", "isPremium": false }, "expectedPerSpec": 29, "note": "dokladne dopasowanie \"EU\"" },
            { "input": { "weightKg": 1, "zone": "WORLD", "isPremium": false }, "expectedPerSpec": 79, "note": "galaz domyslna" },
            { "input": { "weightKg": 1, "zone": "pl", "isPremium": false }, "expectedPerSpec": 79, "note": "porownanie jest case-sensitive - \"pl\" wpada w galaz domyslna" },
            { "input": { "weightKg": 1, "zone": "PL ", "isPremium": false }, "expectedPerSpec": 79, "note": "brak trim() - spacja konczaca lamie dopasowanie" },
            { "input": { "weightKg": 1, "zone": "", "isPremium": false }, "expectedPerSpec": 79, "note": "pusty string to legalne wejscie, nie blad" }
          ]
        },
        {
          "id": "SHIP-R2",
          "rule": "Doplata wagowa naliczana jednorazowo do stawki bazowej: waga > 30 kg daje +40.00 PLN, waga > 10 kg i <= 30 kg daje +15.00 PLN, waga <= 10 kg nie daje doplaty. Progi sa scisle (>) - wartosc rowna progowi nalezy do nizszego przedzialu.",
          "specSection": "Sekcja 1: Koszt dostawy / Doplata wagowa",
          "boundaries": [
            { "input": { "weightKg": 10, "zone": "PL", "isPremium": false }, "expectedPerSpec": 12, "note": "10 kg wlacznie - brak doplaty (dolna strona progu 10)" },
            { "input": { "weightKg": 10.0001, "zone": "PL", "isPremium": false }, "expectedPerSpec": 27, "note": "pierwsza wartosc powyzej 10 - doplata +15" },
            { "input": { "weightKg": 30, "zone": "PL", "isPremium": false }, "expectedPerSpec": 27, "note": "30 kg wlacznie - nadal +15 (dolna strona progu 30)" },
            { "input": { "weightKg": 30.0001, "zone": "PL", "isPremium": false }, "expectedPerSpec": 52, "note": "pierwsza wartosc powyzej 30 - doplata +40, nie +55 (doplaty sie nie kumuluja)" },
            { "input": { "weightKg": 100, "zone": "PL", "isPremium": false }, "expectedPerSpec": 52, "note": "gorna dopuszczalna waga" }
          ]
        },
        {
          "id": "SHIP-R3",
          "rule": "Klient premium (isPremium === true) placi 80% kwoty wyliczonej po stawce bazowej i doplacie wagowej.",
          "specSection": "Sekcja 1: Koszt dostawy / Rabat premium",
          "boundaries": [
            { "input": { "weightKg": 1, "zone": "PL", "isPremium": true }, "expectedPerSpec": 9.6, "note": "12 * 0.8" },
            { "input": { "weightKg": 1, "zone": "PL", "isPremium": false }, "expectedPerSpec": 12, "note": "przelacznik false" },
            { "input": { "weightKg": 20, "zone": "EU", "isPremium": true }, "expectedPerSpec": 35.2, "note": "(29 + 15) * 0.8" },
            { "input": { "weightKg": 100, "zone": "WORLD", "isPremium": true }, "expectedPerSpec": 95.2, "note": "(79 + 40) * 0.8 - maksymalny rabat premium" },
            { "input": { "weightKg": 30.0001, "zone": "PL", "isPremium": true }, "expectedPerSpec": 41.6, "note": "(12 + 40) * 0.8 - rabat po doplacie, nie przed" }
          ]
        },
        {
          "id": "SHIP-R4",
          "rule": "Wynik jest kwota w zlotych zaokraglona do dwoch miejsc po przecinku.",
          "specSection": "Sekcja 1: Koszt dostawy / Wynik",
          "boundaries": [
            { "input": { "weightKg": 10.5, "zone": "PL", "isPremium": true }, "expectedPerSpec": 21.6, "note": "27 * 0.8 - mnozenie float musi zostac dociete do 2 miejsc" },
            { "input": { "weightKg": 31, "zone": "EU", "isPremium": true }, "expectedPerSpec": 55.2, "note": "69 * 0.8" }
          ],
          "invariant": "Math.abs(result * 100 - Math.round(result * 100)) < 1e-9"
        }
      ],

      "inputDomains": {
        "weightKg": {
          "type": "number",
          "hasRequiredTextFormat": false,
          "allowedRange": { "min": 0, "minInclusive": false, "max": 100, "maxInclusive": true },
          "description": "Waga w kilogramach. Skonczona liczba z przedzialu (0, 100]. Nie musi byc calkowita.",
          "equivalenceClasses": [
            { "name": "nie-liczba-skonczona", "valid": false, "probes@expr": ["NaN", "Infinity", "-Infinity"], "raises": "TypeError" },
            { "name": "zero-lub-ujemna", "valid": false, "probes": [0, -0.01, -1, -100], "probes@expr": ["-0"], "raises": "RangeError", "note": "-0 <= 0 jest prawdziwe, wiec -0 tez jest odrzucone" },
            { "name": "lekka", "valid": true, "probes": [0.01, 1, 5, 9.99, 10], "probes@expr": ["Number.MIN_VALUE"] },
            { "name": "srednia", "valid": true, "probes": [10.0001, 10.5, 15, 29.99, 30] },
            { "name": "ciezka", "valid": true, "probes": [30.0001, 50, 99.99, 100] },
            { "name": "ponad-limit", "valid": false, "probes": [100.0001, 101, 1000], "raises": "RangeError" }
          ],
          "boundaryValues": [0, 0.01, 10, 10.0001, 30, 30.0001, 100, 100.0001],
          "boundaryValues@expr": ["Number.MIN_VALUE", "-0", "NaN", "Infinity", "-Infinity"]
        },
        "zone": {
          "type": "string",
          "hasRequiredTextFormat": false,
          "formatNote": "Parametr NIE ma wymaganego formatu tekstowego: SPEC dopuszcza `dowolna inna wartosc` i mapuje ja na stawke 79.00 PLN, wiec zadna wartosc string nie jest bledna. Typ `Zone = \"PL\" | \"EU\" | \"WORLD\"` w src/pricing.ts:1 jest tylko podpowiedzia kompilatora - sygnatura funkcji przyjmuje `string`.",
          "allowedRange": "dowolny string",
          "significantValues": ["PL", "EU", "WORLD"],
          "fallbackValue": "kazdy string rozny od \"PL\" i \"EU\"",
          "equivalenceClasses": [
            { "name": "strefa-krajowa", "probes": ["PL"], "baseRate": 12 },
            { "name": "strefa-unijna", "probes": ["EU"], "baseRate": 29 },
            { "name": "strefa-pozostala", "probes": ["WORLD", "US", "pl", "eu", "PL ", " PL", "Pl", "", "PLN", "EUR", "🇵🇱"], "baseRate": 79 }
          ]
        },
        "isPremium": {
          "type": "boolean",
          "hasRequiredTextFormat": false,
          "allowedRange": [true, false],
          "description": "Rabat 20% stosowany tylko dla dokladnie `true` (SPEC mowi `isPremium === true`).",
          "boundaryValues": [true, false]
        }
      },

      "errors": [
        {
          "type": "TypeError",
          "message": "weight must be a finite number",
          "condition": "Number.isFinite(weightKg) === false",
          "specSection": "Sekcja 1 / Walidacja wejscia",
          "triggers@expr": ["NaN", "Infinity", "-Infinity"],
          "precedence": 1
        },
        {
          "type": "RangeError",
          "message": "weight must be positive",
          "condition": "weightKg <= 0",
          "specSection": "Sekcja 1 / Walidacja wejscia",
          "triggers": [0, -0.01, -1, -100],
          "triggers@expr": ["-0"],
          "precedence": 2
        },
        {
          "type": "RangeError",
          "message": "weight above carrier limit",
          "condition": "weightKg > 100",
          "specSection": "Sekcja 1 / Walidacja wejscia",
          "triggers": [100.0001, 101, 1e6],
          "precedence": 3
        }
      ],
      "errorPrecedenceNote": "Walidacja jest sekwencyjna: TypeError (skonczonosc) przed RangeError (znak) przed RangeError (limit). `zone` i `isPremium` nie sa nigdy walidowane - nie ma dla nich zadnego bledu.",

      "statefulSequences": [],
      "specVsCode": [
        { "verdict": "zgodne", "note": "src/pricing.ts implementuje sekcje 1 bez rozbieznosci wobec SPEC 1.4." }
      ]
    },

    {
      "module": "src/invoiceId.ts",
      "function": "parseInvoiceId",
      "kind": "pure-function",
      "signature": "parseInvoiceId(raw: string): { year: number; month: number; seq: number }",
      "returns": {
        "type": "object",
        "fields": {
          "year": { "type": "integer", "range": [2000, 2100] },
          "month": { "type": "integer", "range": [1, 12], "note": "bez wiodacego zera - \"09\" -> 9" },
          "seq": { "type": "integer", "range": [1, 9999], "note": "bez wiodacych zer - \"0042\" -> 42" }
        }
      },

      "rules": [
        {
          "id": "INV-R1",
          "rule": "Identyfikator ma postac FV/RRRR/MM/NNNN: staly prefiks \"FV\", rok jako dokladnie 4 cyfry, miesiac jako dokladnie 2 cyfry z zakresu 01-12, numer kolejny jako dokladnie 4 cyfry. Separatorem jest ukosnik.",
          "specSection": "Sekcja 2: Identyfikator faktury / Format",
          "boundaries": [
            { "input": { "raw": "FV/2026/09/0042" }, "expectedPerSpec": { "year": 2026, "month": 9, "seq": 42 }, "note": "przyklad kanoniczny ze SPEC" },
            { "input": { "raw": "FV/2026/01/0001" }, "expectedPerSpec": { "year": 2026, "month": 1, "seq": 1 }, "note": "dolna granica miesiaca i numeru" },
            { "input": { "raw": "FV/2026/12/9999" }, "expectedPerSpec": { "year": 2026, "month": 12, "seq": 9999 }, "note": "gorna granica miesiaca i numeru" },
            { "input": { "raw": "FV/2026/00/0001" }, "raises": "Error: malformed invoice id", "note": "miesiac 00 - ponizej dolnej granicy" },
            { "input": { "raw": "FV/2026/13/0001" }, "raises": "Error: malformed invoice id", "note": "miesiac 13 - powyzej gornej granicy" },
            { "input": { "raw": "FV/2026/9/0042" }, "raises": "Error: malformed invoice id", "note": "miesiac 1-cyfrowy - `dokladnie dwie cyfry`" },
            { "input": { "raw": "FV/2026/009/0042" }, "raises": "Error: malformed invoice id", "note": "miesiac 3-cyfrowy" },
            { "input": { "raw": "FV/2026/09/042" }, "raises": "Error: malformed invoice id", "note": "numer 3-cyfrowy - `dokladnie cztery cyfry`" },
            { "input": { "raw": "FV/2026/09/00042" }, "raises": "Error: malformed invoice id", "note": "numer 5-cyfrowy" },
            { "input": { "raw": "FV/26/09/0042" }, "raises": "Error: malformed invoice id", "note": "rok 2-cyfrowy" }
          ]
        },
        {
          "id": "INV-R2",
          "rule": "Biale znaki na poczatku i koncu wartosci sa ignorowane (trim). Biale znaki WEWNATRZ identyfikatora nie sa dopuszczalne.",
          "specSection": "Sekcja 2: Identyfikator faktury / Format",
          "boundaries": [
            { "input": { "raw": "  FV/2026/09/0042  " }, "expectedPerSpec": { "year": 2026, "month": 9, "seq": 42 }, "note": "spacje z obu stron" },
            { "input": { "raw": "\tFV/2026/09/0042\n" }, "expectedPerSpec": { "year": 2026, "month": 9, "seq": 42 }, "note": "tab i newline tez sa trimowane" },
            { "input": { "raw": "FV /2026/09/0042" }, "raises": "Error: malformed invoice id", "note": "spacja wewnatrz" },
            { "input": { "raw": "FV/2026/09/00 42" }, "raises": "Error: malformed invoice id", "note": "spacja wewnatrz numeru" },
            { "input": { "raw": "   " }, "raises": "Error: malformed invoice id", "note": "same biale znaki -> po trim pusty string" }
          ]
        },
        {
          "id": "INV-R3",
          "rule": "Rok musi lezec w zakresie 2000-2100 wlacznie. Rok skladniowo poprawny (4 cyfry) ale poza zakresem daje RangeError, nie Error.",
          "specSection": "Sekcja 2: Identyfikator faktury / Walidacja",
          "boundaries": [
            { "input": { "raw": "FV/1999/12/0001" }, "raises": "RangeError: year out of supported range", "note": "rok - 1 od dolnej granicy" },
            { "input": { "raw": "FV/2000/01/0001" }, "expectedPerSpec": { "year": 2000, "month": 1, "seq": 1 }, "note": "dolna granica wlacznie" },
            { "input": { "raw": "FV/2100/12/9999" }, "expectedPerSpec": { "year": 2100, "month": 12, "seq": 9999 }, "note": "gorna granica wlacznie" },
            { "input": { "raw": "FV/2101/01/0001" }, "raises": "RangeError: year out of supported range", "note": "rok + 1 od gornej granicy" },
            { "input": { "raw": "FV/0000/01/0001" }, "raises": "RangeError: year out of supported range", "note": "skrajnie niski rok 4-cyfrowy" },
            { "input": { "raw": "FV/9999/12/9999" }, "raises": "RangeError: year out of supported range", "note": "skrajnie wysoki rok 4-cyfrowy" }
          ]
        },
        {
          "id": "INV-R4",
          "rule": "Numer kolejny rowny 0000 jest niedopuszczalny (RangeError). Najmniejszy dopuszczalny numer to 0001.",
          "specSection": "Sekcja 2: Identyfikator faktury / Walidacja",
          "boundaries": [
            { "input": { "raw": "FV/2026/09/0000" }, "raises": "RangeError: sequence number must not be zero" },
            { "input": { "raw": "FV/2026/09/0001" }, "expectedPerSpec": { "year": 2026, "month": 9, "seq": 1 }, "note": "pierwsza dopuszczalna wartosc" }
          ]
        },
        {
          "id": "INV-R5",
          "rule": "Wynik zwraca year, month i seq jako liczby calkowite bez wiodacych zer (parsowanie dziesietne, nie oktalne).",
          "specSection": "Sekcja 2: Identyfikator faktury / Wynik",
          "boundaries": [
            { "input": { "raw": "FV/2026/09/0042" }, "expectedPerSpec": { "year": 2026, "month": 9, "seq": 42 }, "note": "\"09\" -> 9 (nie 0o9 / NaN), \"0042\" -> 42" },
            { "input": { "raw": "FV/2026/08/0008" }, "expectedPerSpec": { "year": 2026, "month": 8, "seq": 8 }, "note": "\"08\" i \"0008\" - cyfry, ktore w notacji oktalnej byly by bledne" },
            { "input": { "raw": "FV/2026/10/0100" }, "expectedPerSpec": { "year": 2026, "month": 10, "seq": 100 }, "note": "zero w srodku liczby" }
          ],
          "invariant": "Number.isInteger(r.year) && Number.isInteger(r.month) && Number.isInteger(r.seq)"
        }
      ],

      "inputDomains": {
        "raw": {
          "type": "string",
          "hasRequiredTextFormat": true,
          "pattern": "^\\s*FV/(\\d{4})/(0[1-9]|1[0-2])/(\\d{4})\\s*$",
          "patternNote": "Wzorzec obejmuje trim. Sam kod dopasowuje `^FV\\/(\\d{4})\\/(0[1-9]|1[0-2])\\/(\\d{4})$` do `raw.trim()` (src/invoiceId.ts:16). Dopasowanie wzorca to warunek KONIECZNY, nie wystarczajacy - po nim jeszcze obowiazuja INV-R3 (rok 2000-2100) i INV-R4 (numer != 0000).",
          "patternFullyValid": "^\\s*FV/(20(0\\d|[1-9]\\d)|2100)/(0[1-9]|1[0-2])/(?!0000)(\\d{4})\\s*$",
          "patternFullyValidNote": "Wzorzec wartosci, ktore przechodza CALA walidacje (format + zakres roku + niezerowy numer) - tego wzorca powinien uzyc generator do produkcji wejsc pozytywnych.",
          "digitsNote": "`\\d` w tym wyrazeniu jest ASCII-only (brak flagi `u`), wiec cyfry innych systemow pisma (np. arabsko-indyjskie \"٢٠٢٦\") NIE pasuja i daja `Error: malformed invoice id`.",
          "caseSensitive": true,
          "validExamples": [
            "FV/2026/09/0042",
            "FV/2000/01/0001",
            "FV/2100/12/9999",
            "  FV/2026/09/0042  ",
            "FV/2026/08/0008",
            "FV/2050/10/0100",
            "\tFV/2099/11/1234\n"
          ],
          "invalidExamples": [
            { "value": "fv/2026/09/0042", "reason": "prefiks malymi literami - prefiks \"FV\" jest staly i case-sensitive", "raises": "Error: malformed invoice id" },
            { "value": "FV-2026-09-0042", "reason": "myslnik zamiast ukosnika", "raises": "Error: malformed invoice id" },
            { "value": "FV/2026/09/0042/1", "reason": "nadmiarowy segment na koncu", "raises": "Error: malformed invoice id" },
            { "value": "FV/2026/9/0042", "reason": "miesiac jednocyfrowy", "raises": "Error: malformed invoice id" },
            { "value": "FV/2026/13/0001", "reason": "miesiac poza 01-12", "raises": "Error: malformed invoice id" },
            { "value": "FV/2026/09/042", "reason": "numer trzycyfrowy", "raises": "Error: malformed invoice id" },
            { "value": "", "reason": "pusty string", "raises": "Error: malformed invoice id" },
            { "value": "FV/2026/09/00A2", "reason": "litera w numerze kolejnym", "raises": "Error: malformed invoice id" },
            { "value": "FV/1999/12/0001", "reason": "format poprawny, rok ponizej 2000", "raises": "RangeError: year out of supported range" },
            { "value": "FV/2101/01/0001", "reason": "format poprawny, rok powyzej 2100", "raises": "RangeError: year out of supported range" },
            { "value": "FV/2026/09/0000", "reason": "format poprawny, numer kolejny zerowy", "raises": "RangeError: sequence number must not be zero" }
          ],
          "nonStringProbes@expr": ["null", "undefined", "42", "{}", "[]", "true", "Symbol('FV/2026/09/0042')"],
          "nonStringProbesRaises": "TypeError: invoice id must be a string"
        }
      },

      "errors": [
        {
          "type": "TypeError",
          "message": "invoice id must be a string",
          "condition": "typeof raw !== \"string\"",
          "specSection": "Sekcja 2 / Walidacja",
          "triggers@expr": ["null", "undefined", "42", "{}", "['FV/2026/09/0042']", "new String('FV/2026/09/0042')"],
          "precedence": 1,
          "note": "Obiekt `new String(...)` ma typeof \"object\", wiec tez daje TypeError, mimo ze `.trim()` by zadzialal."
        },
        {
          "type": "Error",
          "message": "malformed invoice id",
          "condition": "raw.trim() nie pasuje do wzorca formatu",
          "specSection": "Sekcja 2 / Walidacja",
          "triggers": ["", "   ", "FV/2026/9/0042", "FV/2026/13/0001", "fv/2026/09/0042", "FV-2026-09-0042", "FV/2026/09/00A2"],
          "precedence": 2
        },
        {
          "type": "RangeError",
          "message": "year out of supported range",
          "condition": "year < 2000 || year > 2100 (sprawdzane dopiero po dopasowaniu formatu)",
          "specSection": "Sekcja 2 / Walidacja",
          "triggers": ["FV/1999/12/0001", "FV/2101/01/0001", "FV/0000/01/0001", "FV/9999/12/9999"],
          "precedence": 3
        },
        {
          "type": "RangeError",
          "message": "sequence number must not be zero",
          "condition": "seq === 0 (sprawdzane dopiero po dopasowaniu formatu i walidacji roku)",
          "specSection": "Sekcja 2 / Walidacja",
          "triggers": ["FV/2026/09/0000", "FV/2000/01/0000"],
          "precedence": 4
        }
      ],
      "errorPrecedenceNote": "Kolejnosc walidacji jest istotna dla oracle: typ -> format -> rok -> numer. Wejscie z wieloma bledami zglasza tylko pierwszy: \"FV/1999/13/0000\" -> `Error: malformed invoice id` (nie RangeError), a \"FV/1999/12/0000\" -> `RangeError: year out of supported range` (nie blad numeru).",

      "statefulSequences": [],
      "specVsCode": [
        { "verdict": "zgodne", "note": "src/invoiceId.ts implementuje sekcje 2 bez rozbieznosci wobec SPEC 1.4." }
      ]
    },

    {
      "module": "src/loyalty.ts",
      "function": "awardPoints",
      "kind": "pure-function",
      "signature": "awardPoints(orderValuePLN: number, lifetimeSpendPLN: number): number",
      "returns": {
        "type": "integer",
        "unit": "punkty lojalnosciowe",
        "range": [0, 5000],
        "invariant": "Number.isInteger(result) && result >= 0 && result <= 5000"
      },

      "rules": [
        {
          "id": "LOY-R1",
          "rule": "Klient otrzymuje 1 punkt za kazde 10 zlotych wartosci zamowienia: punkty = round_half_to_even(orderValuePLN / 10). Zaokraglenie jest BANKIERSKIE - do najblizszej liczby calkowitej, a przy dokladnej polowie do liczby PARZYSTEJ.",
          "specSection": "Sekcja 3: Punkty lojalnosciowe / Przelicznik",
